Describe 'Initialize-GitRepository' {
    It 'initialises a repository in the current directory from a remote' {
        # Arrange
        # The function runs "git init" in the CURRENT directory and then
        # fetches from the remote. The generated test called it without
        # changing directory, so the suite re-initialised the repository it
        # lives in and fetched from a bogus URL - creating a .git directory
        # inside the source tree and rewriting the outer repo's origin and
        # HEAD. The test now runs in a throw-away directory with a local
        # remote, so nothing outside $TestDrive is touched.
        $work = Join-Path $TestDrive 'init-repo'
        $remote = Join-Path $TestDrive 'origin.git'
        New-Item -ItemType Directory -Path $work -Force | Out-Null
        New-Item -ItemType Directory -Path $remote -Force | Out-Null
        & git -C $remote init --bare -q 2>&1 | Out-Null

        Push-Location $work
        try {
            # Act & Assert
            { Initialize-GitRepository -RepoUrl $remote } | Should -Not -Throw
            # The repository really was created where we were standing.
            Test-Path -LiteralPath (Join-Path $work '.git') | Should -BeTrue
        } finally { Pop-Location }
    }
    It 'leaves the repository that hosts the test untouched' {
        # The harness IS a repository in its own right, so the invariant is
        # not "there is no .git here" - it is that the test creates no NEW
        # repository and changes nothing in the one that is there.
        $script:repoRoot = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
        $before = @(Get-ChildItem -LiteralPath $script:repoRoot -Recurse -Force -Directory -Filter '.git' -ErrorAction SilentlyContinue |
            ForEach-Object { $_.FullName })
        $beforeCount = $before.Count

        $work = Join-Path $TestDrive 'untouched'
        New-Item -ItemType Directory -Path $work -Force | Out-Null
        { Initialize-GitRepository -RepoUrl 'https://example.invalid/x.git' -Path $work } | Should -Not -Throw

        $after = @(Get-ChildItem -LiteralPath $script:repoRoot -Recurse -Force -Directory -Filter '.git' -ErrorAction SilentlyContinue |
            ForEach-Object { $_.FullName })
        $after.Count | Should -Be $beforeCount -Because 'a test run must not create a repository inside the source tree'
    }
}
