    It 'removes the lock file in the current directory' {
        # Arrange
        # Clear-GitLock deletes .git/index.lock in the CURRENT directory.
        # The generated test ran it in the source tree, so the suite could
        # delete the lock of the repository it lives in. It now runs in a
        # throw-away directory with a lock file of its own.
